'use strict';
let state, tab='jobs', day=Number(localStorage.getItem('prep-day')||1), timer=null, remaining=25*60, refreshPoll=null;
const prepSaves=new Map(), unsavedPrep=new Set();
let discoveryPlatform='All';
const materialFilters={query:'',category:'All',kind:'All',week:'All'};
let workspaceToolsRegistered=false;
const filters={query:'',region:'All',fit:'All',status:'All',active:true,reviewed:true};
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr=v=>Array.isArray(v)?v:v?[v]:[], list=v=>arr(v).map(x=>`<li>${esc(typeof x==='object'?JSON.stringify(x):x)}</li>`).join('');
const safeUrl=v=>{try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
const link=(u,t)=>u?`<a href="${esc(safeUrl(u))}" target="_blank" rel="noopener noreferrer">${esc(t)}</a>`:'';
const formatDate=d=>d?new Date(d).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'Not checked';
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000)}
async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await r.json();if(!r.ok)throw Error(data.error||`Request failed (${r.status})`);return data}
async function load(){try{const incoming=await api('/api/state');for(const n of unsavedPrep){if(state?.prep_state[String(n)])incoming.prep_state[String(n)]=state.prep_state[String(n)]}state=incoming;render();registerWorkspaceTools();if(state.refresh.running)pollRefresh();if(state.linkedin?.activity?.running)pollLinkedin()}catch(e){$('#app').innerHTML=`<div class="empty"><h2>Workspace unavailable</h2><p>${esc(e.message)}</p><p>Run Start-Dashboard.ps1 from your application_process folder, then reopen its local address.</p><button id="retry">Retry</button></div>`;$('#retry').onclick=load}}
function render(){if(!state)return;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));({jobs:renderJobs,linkedin:renderLinkedin,discovery:renderDiscovery,prep:renderPrep,projects:renderProjects,study:renderStudy,materials:renderMaterials,learning:renderLearning,curriculum:renderCurriculumReview,gaps:renderLiveGaps,resume:renderResume,sources:renderSources,companies:renderCompanies})[tab]();appendLinkedLearning();$('#save-status').textContent=unsavedPrep.size?'Session changes pending':'Saved on this PC'}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});
$('#detail .close').onclick=()=>$('#detail').close();
$('#export').onclick=async()=>{try{download('application-studio-backup.json',JSON.stringify(await api('/api/export'),null,2),'application/json');toast('Backup exported: jobs, notes and prep progress')}catch(e){toast(e.message)}};
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function options(values,current){return values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function filteredJobs(){const q=filters.query.toLowerCase();return state.jobs.filter(j=>(!filters.active||j.status_source==='active')&&(!filters.reviewed||j.reviewed)&&(filters.region==='All'||j.region===filters.region)&&(filters.fit==='All'||j.fit_band===filters.fit)&&(filters.status==='All'||j.application_status===filters.status)&&(!q||[j.title,j.company,j.location,j.requirements,j.description,j.role_track].join(' ').toLowerCase().includes(q))).sort((a,b)=>(a.location_rank??9)-(b.location_rank??9)||({strong:0,possible:1,stretch:2,low:3,'Needs review':4}[a.fit_band]??4)-({strong:0,possible:1,stretch:2,low:3,'Needs review':4}[b.fit_band]??4)||a.company.localeCompare(b.company))}
function renderJobs(){const jobs=filteredJobs(),active=state.jobs.filter(j=>j.status_source==='active'),reviewed=active.filter(j=>j.reviewed),pipeline=state.jobs.filter(j=>['Applied','Interviewing','Offer'].includes(j.application_status));$('#app').innerHTML=`
<div class="stats"><div class="stat"><strong>${active.length}</strong><span>Open in last successful feed</span></div><div class="stat"><strong>${reviewed.length}</strong><span>Resume-reviewed openings</span></div><div class="stat"><strong>${active.filter(j=>j.region==='EU').length}</strong><span>EU openings</span></div><div class="stat"><strong>${pipeline.length}</strong><span>In your application pipeline</span></div></div>
<div class="toolbar"><label class="grow">Find roles<input id="query" placeholder="Company, skill, location or title" value="${esc(filters.query)}"></label><label>Location<select id="region">${options(['All',...new Set(state.jobs.map(j=>j.region))],filters.region)}</select></label><label>Resume fit<select id="fit">${options(['All','strong','possible','stretch','low','Needs review'],filters.fit)}</select></label><label>Application<select id="status">${options(['All','New','Shortlisted','Researching','Applied','Interviewing','Offer','Rejected','Passed'],filters.status)}</select></label><button id="refresh-jobs" class="primary">${state.refresh.running?'Refreshing…':'Refresh live jobs'}</button><a href="/api/jobs.csv">CSV</a></div>
<div class="row space-between section"><div class="row"><label class="checkline"><input id="active-only" type="checkbox" ${filters.active?'checked':''}> Listed roles only</label><label class="checkline"><input id="reviewed-only" type="checkbox" ${filters.reviewed?'checked':''}> Resume-reviewed only</label></div><span class="muted small">${jobs.length} results · EU → Asia → Bangalore → Hyderabad → Mumbai → Pune</span></div>
<p class="small muted">Fit describes evidence overlap, not interview or visa odds. New feed matches need review. Published pay is gross and location-specific; equity is separate. ${state.refresh.running?esc(state.refresh.message):''}</p>
<div class="grid" id="job-grid">${jobs.length?jobs.map(jobCard).join(''):'<div class="empty">No jobs match these filters. Clear a filter or refresh the source feeds.</div>'}</div>`;
$('#query').oninput=e=>{filters.query=e.target.value;const pos=e.target.selectionStart;renderJobs();$('#query').focus();$('#query').setSelectionRange(pos,pos)};
for(const id of ['region','fit','status'])$('#'+id).onchange=e=>{filters[id]=e.target.value;renderJobs()};
$('#active-only').onchange=e=>{filters.active=e.target.checked;renderJobs()};$('#reviewed-only').onchange=e=>{filters.reviewed=e.target.checked;renderJobs()};$('#refresh-jobs').onclick=refreshJobs;
document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>openJob(b.dataset.job));document.querySelectorAll('[data-status]').forEach(s=>s.onchange=()=>saveJob(s.dataset.status,s.value));}
function jobCard(j){const stale=!j.verified_at||Date.now()-new Date(j.verified_at).getTime()>7*86400000;return `<article class="card"><div class="job-head"><div><div class="company">${esc(j.company)}</div><button class="job-title" data-job="${esc(j.id)}">${esc(j.title)}</button></div><span class="chip ${j.fit_band==='strong'?'good':'warn'}">${esc(j.fit_band)}</span></div><p class="muted small">${esc(j.location)} · ${esc(j.role_track||'Engineering')}</p><div class="chips"><span class="chip">${esc(j.status_source)}</span><span class="chip">${esc(j.years_required||'Experience: check posting')}</span>${stale?'<span class="chip warn">Verification older than 7 days</span>':''}</div><div class="job-meta"><div>${esc(j.salary_text||'Pay not published')}</div><div class="muted">${esc(j.visa_text||'Visa / relocation unknown')}</div></div><p class="fit-note">${esc(j.fit_reasons||'Needs review')}</p><div class="card-foot"><select aria-label="Application status for ${esc(j.company)}" data-status="${esc(j.id)}">${options(['New','Shortlisted','Researching','Applied','Interviewing','Offer','Rejected','Passed'],j.application_status)}</select><span>${link(j.apply_url,'Open application ↗')}</span></div><p class="small muted" style="margin:10px 0 0">Checked ${esc(formatDate(j.verified_at))}</p></article>`}
function openJob(id){const j=state.jobs.find(x=>x.id===id);if(!j)return;$('#detail-body').innerHTML=`<p class="company">${esc(j.company)}</p><h2>${esc(j.title)}</h2><p>${esc(j.location)} · ${esc(j.fit_band)} fit</p><div class="row section">${link(j.source_url,'Source listing')}${link(j.apply_url,'Application')}${link(j.verification_source,'Live feed')}</div><h3>Discovery provenance</h3><p>${esc(arr(j.discovered_via).join(', ')||'Initial employer research')} ${link(j.discovery_url,'Discovery page')}</p><h3>Why it matches</h3><p>${esc(j.fit_reasons)}</p><h3>Evidence to strengthen</h3><p>${esc(j.gaps)}</p><h3>Must-haves</h3><p>${esc(j.requirements||'Review the full posting below.')}</p><h3>Preferred / experience</h3><p>${esc(j.preferred||'See listing')} · ${esc(j.years_required||'Not specified')}</p><h3>Pay and mobility</h3><p>${esc(j.salary_text)} ${link(j.compensation_evidence_url,'Pay source')}</p><p>${esc(j.visa_text)} ${link(j.visa_evidence_url,'Mobility source')}</p><h3>Mission / company evidence</h3><p>${esc(j.company_mission||'Research before applying')}</p><p>${esc(j.founder_or_funding_evidence||'Not researched')} ${link(j.company_evidence_url||j.source_url,'Company evidence')}</p><p class="small muted">Comparable-background hiring: ${esc(j.background_hiring_evidence||'Not verified. Relocation policy or a diverse team does not prove a comparable hire.')}</p><label for="job-notes">Your notes — referrals, founder questions, follow-up dates</label><textarea id="job-notes">${esc(j.notes)}</textarea><button id="save-job-notes" class="primary">Save notes</button>${j.description?`<details><summary>Topics detected in latest feed</summary><pre>${esc(j.description)}</pre></details>`:''}<p class="small muted" style="margin-top:15px">${esc(j.verification_method||'Public ATS API')} · ${esc(formatDate(j.verified_at))}</p>`;$('#save-job-notes').onclick=()=>saveJob(id,j.application_status,$('#job-notes').value);$('#detail').showModal()}
async function saveJob(id,status,notes){const j=state.jobs.find(x=>x.id===id);try{const newNotes=notes??j.notes;await api('/api/job-state',{id,status,notes:newNotes});j.application_status=status;j.notes=newNotes;toast('Saved');if(tab==='jobs')renderJobs()}catch(e){toast(e.message)}}
async function refreshJobs(){try{await api('/api/refresh',{});state.refresh.running=true;render();pollRefresh()}catch(e){toast(e.message)}}
function pollRefresh(){if(refreshPoll)return;refreshPoll=setInterval(async()=>{try{state.refresh=await api('/api/refresh-status');if(!state.refresh.running){clearInterval(refreshPoll);refreshPoll=null;await load();toast(state.refresh.message)}else if(tab==='sources')renderSources();else if(tab==='jobs'){const b=$('#refresh-jobs');if(b)b.textContent=`Checking ${state.refresh.completed}/${state.refresh.total}…`}}catch(e){clearInterval(refreshPoll);refreshPoll=null;toast(e.message)}},2000)}
function tasksFor(d){return arr(d.core_tasks).map((t,i)=>typeof t==='string'?{task:t,minutes:25,done_when:'Record the result',index:i}:{...t,index:i})}
function dayState(n){return state.prep_state[String(n)]||{tasks:[],notes:'',energy:'standard',minimum_done:false}}
function complete(d){const t=tasksFor(d),s=dayState(d.day);return t.length>0&&t.every((_,i)=>s.tasks?.includes(i))}
function dailyMaterials(d){const theory=d.ai_theory;return `<div class="learning-note section">${d.learning_note?`<p class="small muted">${esc(d.learning_note)}</p>`:''}${theory?`<span class="eyebrow">AI THEORY INTO PRACTICE</span><h3>${esc(theory.title)}</h3><p>${esc(theory.subtext)}</p><div class="resource-list">${arr(theory.resources).map(r=>link(r.url,r.label||r.title)).join('')}</div>`:''}<button class="link" data-open-materials="All">Browse learning materials & practice</button></div>`}
function exerciseStartDay(week){const match=String(week).match(/^W(\d+)/i)||String(week).match(/^(\d+)$/);if(!match)return null;const start=(Number(match[1])-1)*7+1;return arr(state.plan.days).some(d=>d.day===start)?start:null}
function renderMaterials(){
const library=state.plan.learning_library||{},resources=arr(library.resources),exercises=arr(library.exercises),query=materialFilters.query.toLowerCase().trim();
const matches=(item,fields)=>!query||fields.map(k=>arr(item[k]).join(' ')).join(' ').toLowerCase().includes(query);
const categoryMatches=item=>materialFilters.category==='All'||item.category===materialFilters.category;
const visible=resources.filter(r=>categoryMatches(r)&&(materialFilters.kind==='All'||r.kind===materialFilters.kind)&&matches(r,['title','category','kind','description','use']));
const practice=exercises.filter(e=>categoryMatches(e)&&(materialFilters.week==='All'||String(e.week)===materialFilters.week)&&matches(e,['title','category','task','evidence']));
const strands=arr(library.strands).filter(s=>categoryMatches(s)&&matches(s,['title','category','depth','subtext'])),categories=['All',...new Set([...resources,...exercises,...arr(library.strands)].map(r=>r.category).filter(Boolean))];
$('#app').innerHTML=`<section class="narrow section"><span class="eyebrow">LEARN · APPLY · EXPLAIN</span><h2>Your learning library</h2><p>${esc(library.summary||'Study references, bounded practice and evidence for the complete preparation plan.')}</p>${library.theory_policy?`<p class="notice">${esc(arr(library.theory_policy).join(' '))}</p>`:''}<a href="/learning-library-plan.html" target="_blank" rel="noopener">Open the standalone learning plan</a></section>
<div class="toolbar"><label class="grow">Find materials or practice<input id="material-query" type="search" value="${esc(materialFilters.query)}" placeholder="Embeddings, SQL, concurrency, evaluation…"></label><label>Topic<select id="material-category">${options(categories,materialFilters.category)}</select></label><label>Resource type<select id="material-kind">${options(['All',...new Set(resources.map(r=>r.kind).filter(Boolean))],materialFilters.kind)}</select></label><label>Practice week<select id="material-week">${options(['All',...new Set(exercises.map(e=>String(e.week)))],materialFilters.week)}</select></label></div>
<section class="section"><h2>References <span class="small muted">${visible.length} materials</span></h2><div class="grid materials-grid">${visible.length?visible.map(r=>`<article class="card material-card"><div class="chips"><span class="chip">${esc(r.category)}</span><span class="chip">${esc(r.kind)}</span><span class="chip good">${esc(r.access)}</span></div><h3>${link(r.url,r.title)}</h3><p>${esc(r.description)}</p><p class="small muted"><strong>Use it for:</strong> ${esc(r.use)}</p></article>`).join(''):'<p class="empty">No references match. Try a broader search or another topic.</p>'}</div></section>
<section class="section"><h2>Core topics and depth</h2><div class="grid">${strands.map(s=>`<article class="card"><span class="eyebrow">${esc(s.category)} · ${esc(s.depth)}</span><h3>${esc(s.title)}</h3><p>${esc(s.subtext)}</p><div class="resource-list">${arr(s.resource_ids).map(id=>resources.find(r=>r.id===id)).filter(Boolean).map(r=>link(r.url,r.title)).join('')}</div></article>`).join('')}</div></section>
<section class="section"><h2>Practice from the library <span class="small muted">${practice.length} exercises</span></h2><p class="small muted">Use the original prompts below inside your planned timeboxes. Save the resulting evidence in your daily session notes.</p><div class="grid">${practice.length?practice.map(e=>`<article class="card"><span class="eyebrow">${esc(/^\d+$/.test(String(e.week))?`WEEK ${e.week}`:e.week)} · ${esc(e.category)} · ${esc(typeof e.minutes==='number'?`${e.minutes} MIN`:String(e.minutes||'').replace(/m\b/gi,' min'))}</span><h3>${esc(e.title)}</h3><p>${esc(e.task)}</p><p class="notice"><strong>Evidence:</strong> ${esc(e.evidence)}</p>${exerciseStartDay(e.week)!==null?`<button data-exercise-week="${esc(e.week)}">Open assigned study week</button>`:''}</article>`).join(''):'<p class="empty">No practice matches these topic, week and search filters.</p>'}</div></section>
<section class="section"><h2>Readiness checkpoints</h2><div class="grid">${arr(library.checkpoints).map(c=>`<article class="card checkpoint-card"><span class="eyebrow">DAY ${esc(c.day)}</span><h3>${esc(c.title)}</h3><ul>${list(c.criteria)}</ul><button data-checkpoint-day="${esc(c.day)}">Open checkpoint session</button></article>`).join('')}</div></section>
${arr(library.weekly_allocations).length?`<section class="section"><h2>Your 21-hour week</h2><p class="small muted">Allocations below are in hours. Weekend build and test time is part of the weekly total.</p><div class="table-wrap"><table><thead><tr><th>Stage</th><th>DSA</th><th>Systems</th><th>AI theory / learning</th><th>Career</th><th>Weekend</th><th>Total</th></tr></thead><tbody>${library.weekly_allocations.map(a=>`<tr>${['label','dsa','systems','ai','career','weekend','total'].map(k=>`<td>${esc(a[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`:''}<p class="small muted">${esc(library.source_note)}</p>`;
$('#material-query').oninput=e=>{materialFilters.query=e.target.value;const pos=e.target.selectionStart;renderMaterials();$('#material-query').focus();$('#material-query').setSelectionRange(pos,pos)};
for(const key of ['category','kind','week'])$('#material-'+key).onchange=e=>{materialFilters[key]=e.target.value;renderMaterials()};
document.querySelectorAll('[data-exercise-week]').forEach(b=>b.onclick=()=>{const start=exerciseStartDay(b.dataset.exerciseWeek);if(start===null)return;day=start;tab='prep';render()});document.querySelectorAll('[data-checkpoint-day]').forEach(b=>b.onclick=()=>{day=Number(b.dataset.checkpointDay);tab='prep';render()});
}
function renderPrep(){const days=state.plan.days||[],d=days.find(x=>x.day===day)||days[0];if(!d){$('#app').innerHTML='<div class="empty">The detailed daily plan is being assembled.</div>';return}day=d.day;localStorage.setItem('prep-day',String(day));const s=dayState(day),tasks=tasksFor(d),done=days.filter(complete).length,checkpointDays=days.filter(x=>x.day<=70),checkpointDone=checkpointDays.filter(complete).length,currentWeek=Number(d.week)||Math.ceil(day/7),weeks=[...new Set(days.map(x=>Number(x.week)||Math.ceil(x.day/7)))];$('#app').innerHTML=`<div class="split"><aside class="sticky"><h2>Your next session</h2><p class="muted small">${done}/${days.length} standard days complete. Minimum days count as showing up; they do not pretend the full deliverable shipped.</p><div class="progress"><span style="width:${done/days.length*100}%"></span></div><p class="small muted">Day 70 interview checkpoint: ${checkpointDone}/${checkpointDays.length} standard days complete. Review the readiness criteria in Materials.</p><label class="week-picker">Browse a week<select id="prep-week">${weeks.map(w=>`<option value="${w}" ${w===currentWeek?'selected':''}>Week ${w} · days ${(w-1)*7+1}–${Math.min(w*7,days[days.length-1].day)}</option>`).join('')}</select></label><div class="day-grid">${days.filter(x=>(Number(x.week)||Math.ceil(x.day/7))===currentWeek).map(x=>`<button data-day="${x.day}" class="${x.day===day?'active':''} ${complete(x)?'complete':''}" aria-label="Day ${x.day}${complete(x)?' complete':''}">${x.day}${complete(x)?' ✓':''}</button>`).join('')}</div><p class="muted small" style="margin-top:15px">No dates. Missed a day? Resume here. Carry at most one unfinished task; never double tomorrow.</p><label>Session mode<select id="energy">${options(['minimum','standard','stretch'],s.energy||'standard')}</select></label></aside><section><div class="row space-between"><span class="eyebrow">DAY ${day} · ${esc(state.plan.phases?.find(p=>p.id===d.phase)?.name||d.phase||'Preparation')}</span><div class="row"><button id="previous" ${day===days[0].day?'disabled':''}>← Previous</button><button id="next" ${day===days[days.length-1].day?'disabled':''}>Next →</button></div></div><h2 style="margin-top:12px">${esc(d.title)}</h2>${dailyMaterials(d)}<div class="minimum"><strong>LOW ENERGY · smallest useful start</strong><p style="margin:8px 0">${esc(d.minimum_action||'Open the task and work for 25 minutes.')}</p><label class="checkline"><input type="checkbox" id="minimum-done" ${s.minimum_done?'checked':''}> Minimum session done</label></div><div class="focus"><div><strong>One task. One timer.</strong><p class="small muted">Choose 25 minutes of focus, then a break. Stop the timer when you switch tasks.</p></div><div class="row"><span class="timer" id="timer">${timerText()}</span><button id="timer-toggle">${timer?'Pause':'Start 25 min'}</button><button id="timer-reset">Reset</button></div></div>${s.energy==='minimum'?'<p class="notice">The minimum session is enough today. The standard checklist stays available when you return.</p>':''}<h3>STANDARD · ${tasks.reduce((n,t)=>n+Number(t.minutes||25),0)} focused minutes</h3>${tasks.map((t,i)=>`<div class="task ${s.tasks?.includes(i)?'done':''}"><input type="checkbox" id="task-${i}" data-task="${i}" ${s.tasks?.includes(i)?'checked':''}><label for="task-${i}"><span class="task-title">${esc(t.task||t.title)}</span> <span class="small muted">${esc(t.minutes||25)} min</span><div class="done-when">Done when: ${esc(t.done_when||'Write one concrete result in your notes.')}</div></label></div>`).join('')}<div class="notice"><strong>Today’s proof</strong><p style="margin:7px 0 0">${esc(d.deliverable||d.done_when||'Save your implementation, test result or interview recording.')}</p></div>${d.recall?`<p><strong>Recall:</strong> ${esc(d.recall)}</p>`:''}${d.interview?`<p><strong>Interview connection:</strong> ${esc(d.interview)}</p>`:''}${s.energy==='stretch'&&d.optional_stretch?`<div class="card section"><h3>Optional stretch — never required</h3><p>${esc(d.optional_stretch)}</p></div>`:''}<div class="resource-list section">${arr(d.resources).map((r,i)=>typeof r==='string'?link(r,`Resource ${i+1}`):link(r.url,r.label||r.title||`Resource ${i+1}`)).join('')}</div><label for="prep-notes">Session notes: what worked, what confused you, next tiny step</label><textarea id="prep-notes">${esc(s.notes)}</textarea><button id="save-prep-notes" class="primary">Save session notes</button></section></div>`;
document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{day=Number(b.dataset.day);renderPrep()});$('#prep-week').onchange=e=>{day=days.find(x=>(Number(x.week)||Math.ceil(x.day/7))===Number(e.target.value)).day;renderPrep()};$('#previous').onclick=()=>{day=days[Math.max(0,days.indexOf(d)-1)].day;renderPrep()};$('#next').onclick=()=>{day=days[Math.min(days.length-1,days.indexOf(d)+1)].day;renderPrep()};document.querySelectorAll('[data-open-materials]').forEach(b=>b.onclick=()=>{materialFilters.category=b.dataset.openMaterials||'All';materialFilters.query='';tab='materials';render()});$('#energy').onchange=e=>savePrep({...dayState(day),energy:e.target.value});$('#minimum-done').onchange=e=>savePrep({...dayState(day),minimum_done:e.target.checked});document.querySelectorAll('[data-task]').forEach(c=>c.onchange=()=>{const n=Number(c.dataset.task),selected=new Set(dayState(day).tasks||[]);c.checked?selected.add(n):selected.delete(n);savePrep({...dayState(day),tasks:[...selected]})});$('#save-prep-notes').onclick=()=>savePrep({...dayState(day),notes:$('#prep-notes').value});$('#timer-toggle').onclick=toggleTimer;$('#timer-reset').onclick=()=>{clearInterval(timer);timer=null;remaining=25*60;renderPrep()};}
async function savePrep(next){
const savingDay=day;
next=structuredClone({...next,notes:$('#prep-notes')?.value??next.notes});
state.prep_state[String(savingDay)]=next;
unsavedPrep.add(savingDay);
if(tab==='prep'&&day===savingDay)renderPrep();
$('#save-status').textContent='Saving session…';
const pending=(prepSaves.get(savingDay)||Promise.resolve()).catch(()=>{}).then(()=>api('/api/prep-state',{day:savingDay,state:next}));
prepSaves.set(savingDay,pending);
try{
  await pending;
  if(prepSaves.get(savingDay)===pending){prepSaves.delete(savingDay);unsavedPrep.delete(savingDay)}
  $('#save-status').textContent=unsavedPrep.size?'Session changes pending':'Session saved';
}catch(e){
  if(prepSaves.get(savingDay)===pending)prepSaves.delete(savingDay);
  $('#save-status').textContent='Session not saved — retry';toast(e.message);
}
}
function timerText(){return `${Math.floor(remaining/60).toString().padStart(2,'0')}:${(remaining%60).toString().padStart(2,'0')}`}
