$('#app').innerHTML=`<div class="narrow section"><span class="eyebrow">BUILD · TEST · EXPLAIN</span><h2>${projects.length} independent projects across ${Math.ceil(totalDays/7)} weeks</h2><p>Turn weekday theory into a bounded working experiment. Early builds fit one week; later projects use two weeks to add evaluation, reliability and explainable tradeoffs.</p><p class="notice">Budget 21 focused hours per week, including 6 weekend hours. Stop at each stated boundary and showcase your strongest 2–3 results. Use the learning library alongside the daily tasks.</p><button id="project-materials">Browse project learning materials</button></div><div class="grid">${projects.map(p=>`<article class="card"><span class="eyebrow">${esc(p.timeline||`Weeks ${p.week}–${p.week_end||p.week}`)}</span><h2>${esc(p.name)}</h2><p>${esc(p.problem)}</p><details><summary>Concepts to learn</summary><ol>${list(p.lessons)}</ol></details><h3>${p.multiweek?'Build across the project weeks':'Build'}</h3><p>${esc(p.build)}</p><h3>Test, evaluate and finish</h3><p>${esc(p.test)}</p><p><strong>Proof:</strong> ${esc(p.proof)}</p><p class="notice"><strong>Stop at:</strong> ${esc(p.stop)}</p>${p.integration?`<details><summary>Optional media integration</summary><p>${esc(p.integration)}</p></details>`:''}<div class="resource-list">${link(p.resource,'Project reference')}<button data-project-day="${esc((Number(p.week)-1)*7+1)}">Open project start</button><button data-project-day="${esc((Number(p.week_end||p.week)-1)*7+6)}">Open final build weekend</button></div></article>`).join('')}</div>`;
$('#project-materials').onclick=()=>{materialFilters.category='All';materialFilters.query='';tab='materials';render()};
