function renderGaps(){const a=state.analysis;$('#app').innerHTML=`<div class="narrow"><h2>Your positioning</h2><p>${esc(a.summary)}</p><div class="notice">${esc(a.evidence_note||'Missing evidence is not the same as a missing skill. Resume claims are self-reported until you can explain and substantiate them.')}</div><h3>What already transfers</h3><ul>${list(a.strengths)}</ul><h3>Assumptions to confirm</h3><ul>${list(a.assumptions)}</ul></div><div class="grid section">${arr(a.gaps).map(g=>`<article class="card"><span class="eyebrow">${esc(g.priority||'EVIDENCE GAP')}</span><h3>${esc(g.area||g.skill||g.title)}</h3><p>${esc(g.current||g.current_evidence||g.evidence)}</p><p><strong>Market ask:</strong> ${esc(g.market_ask||g.requirement)}</p><p><strong>Proof to build:</strong> ${esc(g.action||g.proof)}</p>${g.plan_days?`<p class="small muted">${esc(g.plan_days)}</p>`:''}</article>`).join('')}</div>${arr(a.sections).map(s=>`<section class="card section"><h2>${esc(s.title)}</h2>${s.text?`<p>${esc(s.text)}</p>`:''}${s.items?`<ul>${list(s.items)}</ul>`:''}${s.links?`<div class="resource-list">${s.links.map(r=>link(r.url,r.label)).join('')}</div>`:''}</section>`).join('')}<p class="muted small">Detailed analysis and source notes are in the reports folder. No resume metric has been silently upgraded from an estimate to a measured result.</p>`}
function renderSources(){$('#app').innerHTML=`<div class="row space-between section"><div><h2>Refresh coverage</h2><p class="muted">Refresh queries the configured companies’ official ATS feeds. It discovers new matching roles within those boards; it does not search the entire internet.</p></div><button id="refresh-sources" class="primary" ${state.refresh.running?'disabled':''}>Refresh now</button></div><div class="notice">${esc(state.refresh.message)}<br><span class="small">New roles need a resume-fit review. A successful feed missing a previous ID marks it “not_listed”; a failed feed preserves its previous jobs. “Active” means listed at the shown verification time.</span></div><div class="table-wrap"><table><thead><tr><th>Company / board</th><th>Provider</th><th>Latest refresh</th><th>Result</th><th>Coverage</th></tr></thead><tbody>${state.sources.map(s=>`<tr><td>${esc(s.company)}<br>${link(s.careers_url||`https://jobs.ashbyhq.com/${s.board}`,s.board)}</td><td>${esc(s.provider)}</td><td>${esc(formatDate(s.health?.checked_at))}</td><td class="source-status ${s.health&&!s.health.ok?'danger':''}">${esc(s.health?.message||'Seed jobs verified during research; run refresh to update this board.')}</td><td>${s.health?.ok?`${s.health.matching_count} matched / ${s.health.feed_count} total; ${s.health.new_count} new`:'—'}</td></tr>`).join('')}</tbody></table></div><section class="card section" style="margin-top:24px"><h3>Adding companies</h3><p>Add an observed public board token to <code>data/sources.json</code>, then refresh. Supported providers: Ashby, Greenhouse and Lever. Board tokens are public company identifiers, never API keys.</p><p>Companies with custom career pages need a separate manual review or a documented adapter. Discovery maps and job aggregators are useful leads; the employer’s listing is the verification source.</p><p>Do not infer visa support, founder quality, funding runway, or likely pay from the fact a listing exists.</p></section>`;$('#refresh-sources').onclick=refreshJobs;}
function registerWorkspaceTools(){
if(workspaceToolsRegistered||!document.modelContext?.registerTool)return;
workspaceToolsRegistered=true;
const maxDay=Math.max(1,...arr(state.plan.days).map(d=>Number(d.day)));
for(const tool of [{name:'list_job_matches',title:'Read matching jobs',description:'Read the jobs currently matching the visible dashboard filters.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||Object.keys(input).length)throw Error('No arguments expected');return filteredJobs().map(j=>({id:j.id,company:j.company,title:j.title,fit:j.fit_band,status:j.application_status}))}},{name:'open_prep_day',title:'Open a prep day',description:'Navigate to a preparation day without marking any work complete.',inputSchema:{type:'object',properties:{day:{type:'integer',minimum:1,maximum:maxDay}},required:['day'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:async input=>{if(!input||!Number.isInteger(input.day)||!arr(state.plan.days).some(d=>d.day===input.day)||Object.keys(input).length!==1)throw Error(`day must be an available session from 1–${maxDay}`);day=input.day;tab='prep';render();return {day}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}
}
